int16_t q15_mul(int16_t a, int16_t b) {
    int32_t p = int32_t(a) * int32_t(b);   // Q30, |p| <= 2^30
    p += 1 << 14;                          // round half up
    p >>= 15;                              // arithmetic shift (defined in C++20)
    if (p > INT16_MAX) p = INT16_MAX;      // only (-1)*(-1)
    return static_cast<int16_t>(p);
}
// (-32768)*(-32768): p = 2^30 + 2^14 -> >>15 = 32768 -> saturate to 32767

