int16_t fir_q15(const int16_t* x, const int16_t* h, int L) {
    int64_t acc = 0;
    for (int i = 0; i < L; ++i)
        acc += (int32_t(x[i]) * h[i]) >> 15;
    acc = std::clamp<int64_t>(acc, INT16_MIN, INT16_MAX);
    return int16_t(acc);
}
